<?php
$page_title='จัดการ AI Chatbot';require_once __DIR__.'/../includes/auth_check.php';requireAdmin();require_once __DIR__.'/../config/database.php';$db=(new Database())->getConnection();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf(false);try{$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='delete'){$db->prepare('DELETE FROM chat_knowledge_base WHERE id=?')->execute([$id]);$message='ลบความรู้แล้ว';}else{$question=trim($_POST['question']??'');$answer=trim($_POST['answer']??'');$keywords=trim($_POST['keywords']??'');if(mb_strlen($question)<3||mb_strlen($answer)<5||mb_strlen($keywords)<2)throw new RuntimeException('กรอกคำถาม คำตอบ และคำค้นให้ครบ');if($id){$db->prepare('UPDATE chat_knowledge_base SET question=?,answer=?,keywords=?,priority=?,is_active=? WHERE id=?')->execute([$question,$answer,$keywords,(int)($_POST['priority']??0),isset($_POST['is_active'])?1:0,$id]);}else{$db->prepare('INSERT INTO chat_knowledge_base(question,answer,keywords,priority,is_active) VALUES(?,?,?,?,1)')->execute([$question,$answer,$keywords,(int)($_POST['priority']??0)]);}$message='บันทึกความรู้ให้ Chatbot แล้ว';}}catch(Throwable $e){$error=$e->getMessage();}}
$kb=$db->query('SELECT * FROM chat_knowledge_base ORDER BY priority DESC,id DESC')->fetchAll();$stats=['conversations'=>(int)$db->query('SELECT COUNT(*) FROM chat_conversations')->fetchColumn(),'messages'=>(int)$db->query('SELECT COUNT(*) FROM chat_messages')->fetchColumn(),'waiting'=>(int)$db->query("SELECT COUNT(*) FROM chat_conversations WHERE status='waiting_staff'")->fetchColumn()];require __DIR__.'/../includes/admin_header.php';
?><header class="admin-page-header"><div><p class="eyebrow">AI ASSISTANT</p><h1>AI Chatbot และฐานความรู้</h1><p>เพิ่มคำตอบที่ตรวจสอบแล้วเพื่อให้ Bot ตอบได้แม่นยำขึ้น</p></div><span class="status-badge <?php echo appConfig('OPENAI_API_KEY','')!==''?'paid':'pending';?>"><?php echo appConfig('OPENAI_API_KEY','')!==''?'เชื่อม OpenAI แล้ว':'ใช้ระบบตอบภายใน';?></span></header><?php if($message):?><div class="alert alert-success"><?php echo e($message);?></div><?php endif;?><?php if($error):?><div class="alert alert-error"><?php echo e($error);?></div><?php endif;?><section class="stat-grid"><div class="stat-card"><div><small>บทสนทนา</small><strong><?php echo $stats['conversations'];?></strong></div></div><div class="stat-card"><div><small>ข้อความ</small><strong><?php echo $stats['messages'];?></strong></div></div><div class="stat-card"><div><small>รอเจ้าหน้าที่</small><strong><?php echo $stats['waiting'];?></strong></div></div></section><section class="admin-panel" style="padding:22px;margin-top:20px"><h2>เพิ่มความรู้ใหม่</h2><form method="post" class="admin-filter-form" style="align-items:end"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><input type="hidden" name="action" value="save"><label>คำถาม<input name="question" required></label><label>คำค้น คั่นด้วยช่องว่าง<input name="keywords" required></label><label>ลำดับ<input type="number" name="priority" value="0"></label><label style="flex:1">คำตอบ<textarea name="answer" rows="3" required></textarea></label><button class="btn btn-primary">เพิ่มความรู้</button></form></section><section class="admin-panel" style="margin-top:20px"><table><thead><tr><th>คำถาม</th><th>คำค้น</th><th>คำตอบ</th><th></th></tr></thead><tbody><?php foreach($kb as $item):?><tr><td><?php echo e($item['question']);?></td><td><?php echo e($item['keywords']);?></td><td><?php echo e(mb_substr($item['answer'],0,120));?></td><td><form method="post" onsubmit="return confirm('ลบความรู้นี้?')"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?php echo (int)$item['id'];?>"><button class="btn btn-danger">ลบ</button></form></td></tr><?php endforeach;?></tbody></table></section><?php require __DIR__.'/../includes/admin_footer.php';?>
